62	export function validateThresholds(thresholds, metrics) {
63	  const validMetricIds = new Set(metrics.map((m) => m.id));
64	  const errors = [];
65	
66	  Object.entries(thresholds).forEach(([metricId, min]) => {
67	    if (!validMetricIds.has(metricId)) {
68	      errors.push(`Unknown metric: ${metricId}. Valid metrics: ${Array.from(validMetricIds).join(', ')}`);
69	      return;
70	    }
71	    if (typeof min !== 'number' || min < 0 || min > 1) {
72	      errors.push(`Invalid threshold for ${metricId}: minimum must be a number between 0 and 1, got ${min}`);
73	    }
74	  });
75	
76	  return errors;
77	}
