79	export function evaluateThresholds(thresholds, metrics) {
80	  const thresholdResults = Object.entries(thresholds).map(([metricId, min]) => {
81	    const metric = metrics.find((m) => m.id === metricId);
82	    const score = metric?.score ?? null;
83	    const passed = score !== null && score >= min;
84	
85	    return {
86	      metric: metricId,
87	      min,
88	      score,
89	      passed
90	    };
91	  });
92	
93	  const passed = thresholdResults.every((t) => t.passed);
94	
95	  return { thresholds: thresholdResults, passed };
