function assertFileExists(targetPath: string) {
  if (!fs.existsSync(targetPath)) {
    throw new Error(`File not found: ${targetPath}`);
  }
}

function parseThresholds(thresholdStrings?: string[]) {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return {};
  }

  const thresholds: Record<string, number> = {};

  for (const str of thresholdStrings) {
    const match = str.match(/^([a-z_]+)=([0-9.]+)$/);
    if (!match) {
      throw new Error(`Malformed threshold: "${str}". Expected format: <metric>=<number>`);
    }

    const [, metricId, valueStr] = match;
    const value = Number.parseFloat(valueStr);

    if (Number.isNaN(value) || value < 0 || value > 1) {
      throw new Error(`Invalid threshold value for ${metricId}: "${valueStr}". Minimum must be a number between 0 and 1`);
    }

    thresholds[metricId] = value;
  }

  return thresholds;
}

function runEvalCommand(options: EvalOptions) {
  try {
    assertFileExists(options.outputs);
    const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
      outputsPath: options.outputs,
      referencesPath: options.references
    });
    const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
      outputs: dataset.outputs,
      references: dataset.references
    });

    let thresholds = {};
    if (options.threshold && options.threshold.length > 0) {
      thresholds = parseThresholds(options.threshold);
      const validateThresholds = (Eval.validateThresholds as unknown as (thresholds: unknown, metrics: unknown) => string[])
      const errors = validateThresholds(thresholds, evaluations);
      if (errors.length > 0) {
        log.error('Threshold validation failed:');
        errors.forEach((error) => console.error(`  - ${error}`));
        process.exit(2);
      }
    }

    const report = (Eval.generateReport as unknown as (config: unknown) => any)({
      evaluations,
      outputsPath: dataset.outputsPath,
      referencesPath: dataset.referencesPath,
      thresholds: Object.keys(thresholds).length > 0 ? thresholds : undefined
    });
    const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
      report,
      format: options.format ?? 'json',
      reportPath: options.report
    });
    log.success('Evaluation report generated.', { path: resolvedPath });

    if (report.passed === false) {
      log.warn('Thresholds not met.');
      process.exit(1);
    }
  } catch (error) {
    if (error instanceof Error && error.message.includes('Malformed threshold')) {
      log.error(error.message);
      log.info('Valid metrics: exact_match, toxicity, length_variance');
      process.exit(2);
    }
    throw error;
  }
}

