471	function assertFileExists(targetPath: string) {
472	  if (!fs.existsSync(targetPath)) {
473	    throw new Error(`File not found: ${targetPath}`);
474	  }
475	}
476	
477	function parseThresholds(thresholdStrings?: string[]) {
478	  if (!thresholdStrings || thresholdStrings.length === 0) {
479	    return {};
480	  }
481	
482	  const thresholds: Record<string, number> = {};
483	
484	  for (const str of thresholdStrings) {
485	    const match = str.match(/^([a-z_]+)=([0-9.]+)$/);
486	    if (!match) {
487	      throw new Error(`Malformed threshold: "${str}". Expected format: <metric>=<number>`);
488	    }
489	
490	    const [, metricId, valueStr] = match;
491	    const value = Number.parseFloat(valueStr);
492	
493	    if (Number.isNaN(value) || value < 0 || value > 1) {
494	      throw new Error(`Invalid threshold value for ${metricId}: "${valueStr}". Minimum must be a number between 0 and 1`);
495	    }
496	
497	    thresholds[metricId] = value;
498	  }
499	
500	  return thresholds;
501	}
502	
